watch(()=>[props.editing,props.selectedObjectId,props.transformMode,props.transformSpace,props.snap,props.editorGrid,props.placingLabel,props.placingObject],async()=>{if(scene&&props.editing&&!transform)await setupEditor(build);syncEditorSelection();dirty=true;labelsDirty=true;});watch(()=>[props.playing,props.node.props.energy],()=>dirty=true);watch(()=>props.playing,resetStats);watch(()=>props.node.props.exposure,v=>{if(renderer){renderer.toneMappingExposure=v;dirty=true;}});watch(()=>props.node.props.reflectionIntensity,v=>{if(scene){scene.environmentIntensity=v;dirty=true;}});watch(()=>props.node.props.quality,v=>{if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,v==='high'?2:v==='performance'?1:1.5));resetStats();dirty=true;}});watch(()=>props.node.props.ambient,v=>{if(ambient){ambient.intensity=v*.3;dirty=true;}});watch(()=>props.node.props.directional,v=>{if(key){key.intensity=v;renderer.shadowMap.needsUpdate=true;dirty=true;}});
onBeforeUnmount(()=>{build++;cancelAnimationFrame(frame);observer?.disconnect();window.removeEventListener('resize',resize);intersection?.disconnect();mixer?.stopAllAction();controls?.dispose();renderer?.domElement.removeEventListener('pointerdown',pointerDown);renderer?.domElement.removeEventListener('pointerup',pointerUp);renderer?.domElement.removeEventListener('webglcontextlost',lost);transform?.detach();transform?.dispose();composer?.dispose();codeLayer?.dispose();disposeObject(scene);environment?.dispose();draco?.dispose();renderer?.dispose();renderer?.forceContextLoss();});
defineExpose({reset,focus,startFly,focusObject,getView,groundObject,retryObject});
</script>
<template><div ref="host" class="aw-spatial" :data-code-state="codeState" :data-code-hash="codeSource" :data-code-error="codeMessage" :data-code-stats="JSON.stringify(codeStats)" :class="{'is-interactive':interactive,'is-scene-editing':editing,'is-placing-label':placingLabel||placingObject}"><SceneOverlay v-if="node.props.showHUD&&!error" :node="node"/><div v-if="loading" class="aw-scene-state"><span class="aw-loading-ring"></span>正在构建空间场景</div><div v-if="error" class="aw-scene-state error">{{error}}<button @click.stop="load">重新加载</button></div><template v-if="node.props.showPOI&&!loading&&!error"><svg class="aw-poi-leaders" aria-hidden="true"><path v-for="p in labels.filter(l=>l.visible&&l.adjusted)" :key="p.id" :d="`M${p.x} ${p.y}V${p.y+12}L${p.anchorX} ${p.anchorY}`"/></svg><button v-for="p in labels.filter(l=>l.visible)" :key="p.id" class="aw-poi" :class="{'has-leader':p.adjusted}" :style="{left:p.x+'px',top:p.y+'px','--aw-accent':p.color||theme.accent}" @click.stop="focus(p)"><i></i>{{p.name}}<span>↗</span></button></template><div v-if="codeState==='error'" class="aw-code-error" role="alert">{{codeMessage.split('\n')[0]}}</div><SceneInfoCard v-if="selected" :poi="selected" @close="selected=null" @focus="focus(selected)"/><div v-if="interactive&&!editing&&!error" class="aw-scene-controls" @pointerdown.stop><button @click.stop="detailView" title="近看场景细节" aria-label="近看场景细节"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 2H2V6M14 2H18V6M2 14V18H6M18 14V18H14M7 10H13M10 7V13"/></svg></button><button @click.stop="reset" title="重置视角" aria-label="重置视角"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 8A7 7 0 1 1 4 15M3 3V8H8"/></svg></button><button @click.stop="topView" title="俯视场景" aria-label="俯视场景"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M3 3H17V17H3ZM3 10H17M10 3V17"/></svg></button></div></div></template>
